document.addEventListener('DOMContentLoaded',()=>setTimeout(()=>{setupScanReview();const scanner=$('receipt-file');if(scanner)scanner.onchange=event=>event.target.files[0]&&finalRunOCR(event.target.files[0]);const capture=$('camera-capture');if(capture)capture.onclick=()=>{const video=$('camera-video'),canvas=$('camera-canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);canvas.toBlob(blob=>finalRunOCR(blob),'image/jpeg')}},0));
