function exportWorkbook(filteredOnly=false){if(!window.XLSX)return notify('Excel library unavailable. Check your connection.',true);XLSX.writeFile(makeWorkbook(filteredOnly),filteredOnly?'ledgerly-filtered-expenses.xlsx':expenseWorkbookName);XLSX.writeFile(makeUsersWorkbook(),userWorkbookName);state.workbook=makeWorkbook();state.usersWorkbook=makeUsersWorkbook();state.dirty=false;render();notify('Expense and users workbooks downloaded.')}
async function saveWorkbook(){if(!state.workbookHandle)return exportWorkbook(false);try{const writable=await state.workbookHandle.createWritable();await writable.write(XLSX.write(makeWorkbook(),{bookType:'xlsx',type:'array'}));await writable.close();state.workbook=makeWorkbook();state.dirty=false;render();notify('Expense workbook saved. Download the users workbook to persist profile settings.')}catch(error){notify('Could not save that workbook.',true)}}
function importWorkbook(file){if(!file)return;const reader=new FileReader();reader.onload=e=>{try{const wb=XLSX.read(e.target.result,{type:'array'});state.workbook=wb;const sheetName=expenseSheetName(state.profile,wb),rows=XLSX.utils.sheet_to_json(wb.Sheets[sheetName]||{});state.expenses=rows.map(x=>({id:String(x.ID||uid()),profile:state.profile,date:excelDate(x.Date),description:String(x.Description||''),category:String(x.Category||'Other'),originalAmount:Number(x['Original Amount']||0),currency:String(x.Currency||'LKR'),exchangeRate:Number(x['Exchange Rate to LKR']||1),amountLKR:Number(x['Amount in LKR']||0),createdAt:x['Created At']||new Date().toISOString(),updatedAt:x['Updated At']||new Date().toISOString()}));state.dirty=false;render();notify(`Expense tab “${sheetName}” imported.`)}catch(error){notify('That file could not be read as an expense workbook.',true)}};reader.readAsArrayBuffer(file)}
