/* Keep filtered exports separate so they never replace the full in-memory workbook. */
function expenseSheetName(profile,workbook=state.workbook){const base=profile.replace(/[\\/?*\[\]:]/g,' ').trim().slice(0,31)||'User';if(!workbook||!workbook.SheetNames.includes(base))return base;const hash=[...profile].reduce((sum,char)=>((sum*31)+char.charCodeAt(0))>>>0,0).toString(36).slice(0,5);return`${base.slice(0,25)}-${hash}`.slice(0,31)}
function makeWorkbook(filteredOnly=false){const wb=filteredOnly?XLSX.utils.book_new():(state.workbook||XLSX.utils.book_new()),rows=filteredOnly?workbookRows().filter(row=>filtered().some(item=>item.id===row.ID)):workbookRows(),sheetName=expenseSheetName(state.profile,wb),sheetRows=rows.map(row=>{const copy={...row};delete copy.Profile;return copy});wb.Sheets[sheetName]=XLSX.utils.json_to_sheet(sheetRows);if(!wb.SheetNames.includes(sheetName))XLSX.utils.book_append_sheet(wb,wb.Sheets[sheetName],sheetName);return wb}
async function openUsersWithAccess(){try{const[handle]=await window.showOpenFilePicker({types:[{description:'Users Excel workbook',accept:{'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':['.xlsx']}}]});state.usersWorkbookHandle=handle;importUsersWorkbook(await handle.getFile())}catch(error){if(error.name!=='AbortError')notify('Unable to open users workbook.',true)}}
async function saveWorkbook(){if(!state.workbookHandle)return exportWorkbook(false);try{const expenseWritable=await state.workbookHandle.createWritable();await expenseWritable.write(XLSX.write(makeWorkbook(),{bookType:'xlsx',type:'array'}));await expenseWritable.close();if(state.usersWorkbookHandle){const usersWritable=await state.usersWorkbookHandle.createWritable();await usersWritable.write(XLSX.write(makeUsersWorkbook(),{bookType:'xlsx',type:'array'}));await usersWritable.close()}state.workbook=makeWorkbook();state.usersWorkbook=makeUsersWorkbook();state.dirty=false;render();notify(state.usersWorkbookHandle?'Both workbooks saved.':'Expense workbook saved. Download the users workbook to persist profile settings.')}catch(error){notify('Could not save the selected workbook files.',true)}}

/* Netlify can serve the two workbooks beside index.html; fall back silently to manual import. */
