function loadProfileExpenses(){if(!state.workbook||!state.profile)return;const sheetName=expenseSheetName(state.profile,state.workbook),rows=XLSX.utils.sheet_to_json(state.workbook.Sheets[sheetName]||{});state.expenses=rows.map(x=>({id:String(x.ID||uid()),profile:state.profile,date:excelDate(x.Date),description:String(x.Description||''),category:String(x.Category||'Other'),originalAmount:Number(x['Original Amount']||0),currency:String(x.Currency||'LKR'),exchangeRate:Number(x['Exchange Rate to LKR']||1),amountLKR:Number(x['Amount in LKR']||0),createdAt:x['Created At']||new Date().toISOString(),updatedAt:x['Updated At']||new Date().toISOString()}));}
function enterProfile(name){const profile=(name||$('profile-name').value).trim();if(!profile)return notify('Enter a profile name.',true);state.profile=profile;if(!state.profiles.includes(profile)){state.profiles.push(profile);localStorage.setItem('ledgerlyProfiles',JSON.stringify(state.profiles))}state.settings=initialSettings();if(state.usersWorkbook){const settings=XLSX.utils.sheet_to_json(state.usersWorkbook.Sheets.Settings||{}).find(row=>row.Profile===profile);if(settings){state.settings.categories=String(settings.Categories||'').split(',').map(x=>x.trim()).filter(Boolean)||state.settings.categories;state.settings.defaultCurrency=settings['Default Currency']||'LKR';state.settings.theme=settings['Theme Preference']||'dark'}}loadProfileExpenses();localStorage.setItem('ledgerlyLastProfile',profile);showDashboard()}
function runOcrPreprocess(file){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas'),scale=Math.min(2,1800/Math.max(image.width,image.height));canvas.width=image.width*scale;canvas.height=image.height*scale;const context=canvas.getContext('2d');context.drawImage(image,0,0,canvas.width,canvas.height);const pixels=context.getImageData(0,0,canvas.width,canvas.height),data=pixels.data;for(let i=0;i<data.length;i+=4){const gray=(data[i]*.299)+(data[i+1]*.587)+(data[i+2]*.114);const value=gray>175?255:gray<80?0:Math.round((gray-80)*255/95);data[i]=data[i+1]=data[i+2]=value}context.putImageData(pixels,0,0);canvas.toBlob(resolve,'image/png',1)};image.onerror=reject;image.src=URL.createObjectURL(file)})}
function guessReceiptCategory(text){const value=text.toLowerCase();if(/restaurant|cafe|food|grocery|market|bakery|coffee/.test(value))return'Food';if(/uber|taxi|fuel|petrol|bus|transport|parking/.test(value))return'Transport';if(/electric|water|internet|phone|rent|utility/.test(value))return'Bills';if(/cinema|movie|game|music/.test(value))return'Entertainment';if(/mall|shop|store|fashion|clothing/.test(value))return'Shopping';return'Other'}
function parseReceiptCandidates(text){const lines=text.split(/\r?\n/).map(line=>line.replace(/[^\w\s$€£₹¥.,:/-]/g,' ').replace(/\s+/g,' ').trim()).filter(Boolean),currency=/\b(USD|EUR|GBP|INR|AUD|CAD|SGD|JPY|CNY|AED|LKR)\b|[$€£₹¥]/i.exec(text),currencyCode=currency?({$: 'USD','€':'EUR','£':'GBP','₹':'INR','¥':'JPY'}[currency[0]]||currency[0].toUpperCase()):'LKR',dateMatch=text.match(/\b(20\d{2})[-/.](\d{1,2})[-/.](\d{1,2})\b|\b(\d{1,2})[-/.](\d{1,2})[-/.](20\d{2})\b/),date=dateMatch?(dateMatch[1]?`${dateMatch[1]}-${String(dateMatch[2]).padStart(2,'0')}-${String(dateMatch[3]).padStart(2,'0')}`:`${dateMatch[6]}-${String(dateMatch[5]).padStart(2,'0')}-${String(dateMatch[4]).padStart(2,'0')}`):today(),amounts=[...text.matchAll(/(?:[$€£₹¥]\s*)?(\d{1,3}(?:,\d{3})*(?:\.\d{2})|\d+\.\d{2})/g)].map(match=>Number(match[1].replace(/,/g,''))).filter(value=>value>0);const totalLine=lines.find(line=>/total|amount due|grand total|net payable/i.test(line));const total=totalLine?(([...totalLine.matchAll(/\d+(?:,\d{3})*(?:\.\d{2})?/g)].pop()||[])[0]):null;const candidates=[];if(total)candidates.push({description:lines.find(line=>!/[\d]/.test(line)&&line.length>2)||'Receipt total',amount:Number(total.replace(/,/g,''))});amounts.slice(0,6).forEach((amount,index)=>{if(!candidates.some(candidate=>candidate.amount===amount))candidates.push({description:lines.find(line=>line.length>3&&!/[\d]/.test(line)&&!/total|tax|cash|change/i.test(line))||`Receipt item ${index+1}`,amount})});return{candidates:candidates.slice(0,6),currency:currencyCode,date,category:guessReceiptCategory(text)}}
async function runOCR(file){if(!window.Tesseract)return $('ocr-status').textContent='OCR library unavailable. Manual entry is ready.';$('ocr-status').textContent='Enhancing image and reading receipt locally...';try{const processed=await runOcrPreprocess(file),result=await Tesseract.recognize(processed,'eng',{logger:message=>{if(message.status==='recognizing text')$('ocr-status').textContent=`Reading receipt locally... ${Math.round((message.progress||0)*100)}%`}}),parsed=parseReceiptCandidates(result.data.text);if(!parsed.candidates.length)throw Error('No amounts found');$('ocr-status').textContent='Review a suggestion, then click it to use in the form. Nothing was saved.';$('scan-results').innerHTML=parsed.candidates.map((candidate,index)=>`<div class="scan-result" data-index="${index}"><strong>${escapeHtml(candidate.description)}</strong><span>${candidate.amount.toFixed(2)} ${parsed.currency} · ${parsed.date} · ${parsed.category}</span></div>`).join('');document.querySelectorAll('#scan-results .scan-result').forEach((element,index)=>element.onclick=()=>{const candidate=parsed.candidates[index];$('expense-description').value=candidate.description;$('expense-amount').value=candidate.amount;$('expense-date').value=parsed.date;$('expense-currency').value=CURRENCIES.includes(parsed.currency)?parsed.currency:'LKR';$('expense-category').value=(state.settings.categories||DEFAULT_CATEGORIES).includes(parsed.category)?parsed.category:(state.settings.categories||DEFAULT_CATEGORIES)[0];syncRate();closeModal('scan-modal');notify('Receipt suggestion placed in the form. Review before saving.')})}catch(error){$('ocr-status').textContent='Could not confidently read this receipt. Try a brighter, flatter image or enter it manually.'}}
