/* Production mode: the UI talks to Netlify Functions; workbook controls stay hidden. */
const apiRequest=async(path,options={})=>{const response=await fetch(`/api/${path}`,{headers:{'content-type':'application/json'},...options});const raw=await response.text();let data;try{data=raw?JSON.parse(raw):{}}catch(error){throw Error(`${response.status} ${raw||'Empty server response'}`)}if(!response.ok)throw Error(data.error||`Request failed (${response.status})`);return data};
async function loadServerProfiles(){try{const data=await apiRequest('profiles');state.profiles=data.profiles;localStorage.setItem('ledgerlyProfiles',JSON.stringify(state.profiles));renderProfileList()}catch(error){const localFile=location.protocol==='file:';notify(localFile?'Open this project with “npm run dev” or deploy it to Netlify. Direct index.html opening cannot run the API.':'Server storage is unavailable. Check your Netlify configuration.',true)}}
async function loadServerExpenses(){const data=await apiRequest(`expenses?profile=${encodeURIComponent(state.profile)}`);state.expenses=data.expenses.map(normalizeExpense);state.workbook={server:true};state.dirty=false;render()}
function normalizeExpense(x){return{id:String(x.ID||x.id||uid()),profile:x.Profile||state.profile,date:excelDate(x.Date||x.date),description:String(x.Description||x.description||''),category:String(x.Category||x.category||'Other'),originalAmount:Number(x['Original Amount']??x.originalAmount??0),currency:String(x.Currency||x.currency||'LKR'),exchangeRate:Number(x['Exchange Rate to LKR']??x.exchangeRate??1),amountLKR:Number(x['Amount in LKR']??x.amountLKR??0),createdAt:x['Created At']||x.createdAt||new Date().toISOString(),updatedAt:x['Updated At']||x.updatedAt||new Date().toISOString()}}
async function enterProfile(name){const profile=(name||$('profile-name').value).trim();if(!profile)return notify('Enter a profile name.',true);try{const result=await apiRequest('profiles',{method:'POST',body:JSON.stringify({profile})});state.profile=profile;state.profiles=result.profiles;state.settings=initialSettings();localStorage.setItem('ledgerlyProfiles',JSON.stringify(state.profiles));localStorage.setItem('ledgerlyLastProfile',profile);showDashboard();await loadServerExpenses()}catch(error){notify(location.protocol==='file:'?'The API is not running. Start with “npm run dev” or use the deployed Netlify URL.':error.message,true)}}
async function submitExpense(event){event.preventDefault();const amount=Number($('expense-amount').value),rate=Number($('expense-rate').value),description=$('expense-description').value.trim();if(!$('expense-date').value||!description||amount<=0||rate<=0)return showFormMessage('Complete all fields with positive values.',true);const expense={ID:state.editingId||uid(),Profile:state.profile,Date:$('expense-date').value,Description:description,Category:$('expense-category').value,'Original Amount':amount,Currency:$('expense-currency').value,'Exchange Rate to LKR':rate,'Amount in LKR':amount*rate,'Created At':state.editingId?(state.expenses.find(x=>x.id===state.editingId)?.createdAt||new Date().toISOString()):new Date().toISOString(),'Updated At':new Date().toISOString()};try{const result=await apiRequest('expenses',{method:state.editingId?'PUT':'POST',body:JSON.stringify({profile:state.profile,expense})});const wasEditing=Boolean(state.editingId);state.editingId=null;state.expenses=result.expenses.map(normalizeExpense);clearForm();render();showFormMessage(wasEditing?'Expense updated.':'Expense added.');notify('Saved to the expense workbook.')}catch(error){showFormMessage(error.message,true)}}
async function deleteExpense(id){if(!confirm('Delete this expense permanently?'))return;try{const result=await apiRequest('expenses',{method:'DELETE',body:JSON.stringify({profile:state.profile,id})});state.expenses=result.expenses.map(normalizeExpense);render();notify('Expense deleted from the workbook.')}catch(error){notify(error.message,true)}}
