async function saveSettings(){state.settings.defaultCurrency=$('default-currency').value;state.settings.theme=$('theme-select').value;applyTheme(state.settings.theme);try{await apiRequest('settings',{method:'PUT',body:JSON.stringify({profile:state.profile,categories:state.settings.categories.join(', '),defaultCurrency:state.settings.defaultCurrency,theme:state.settings.theme})});notify('Settings saved to the users workbook.')}catch(error){notify(error.message,true)}}
async function runServerOCR(file){const buffer=await file.arrayBuffer(),bytes=new Uint8Array(buffer);let binary='';for(let index=0;index<bytes.length;index+=0x8000)binary+=String.fromCharCode(...bytes.subarray(index,index+0x8000));const result=await apiRequest('ocr',{method:'POST',body:JSON.stringify({mimeType:file.type||'image/jpeg',imageBase64:btoa(binary)})});return result.items||[]}
async function runOCR(file){$('ocr-status').textContent='Reading receipt with server vision AI...';try{const items=await runServerOCR(file);if(!items.length)throw Error();$('ocr-status').textContent='Review a suggestion before saving. Nothing was saved.';$('scan-results').innerHTML=items.map((item,index)=>`<div class="scan-result" data-index="${index}"><strong>${escapeHtml(item.description||'Receipt item')}</strong><span>${item.amount??'Amount not found'} ${item.currency||''} · ${item.date||'Date not found'} · ${item.category||'Other'}</span></div>`).join('');document.querySelectorAll('#scan-results .scan-result').forEach((element,index)=>element.onclick=()=>{const item=items[index];$('expense-description').value=item.description||'Receipt purchase';$('expense-amount').value=item.amount||'';$('expense-date').value=item.date||today();$('expense-currency').value=CURRENCIES.includes(item.currency)?item.currency:'LKR';$('expense-category').value=(state.settings.categories||DEFAULT_CATEGORIES).includes(item.category)?item.category:'Other';syncRate();closeModal('scan-modal');notify('AI suggestion placed in the form. Review before saving.')})}catch(error){$('ocr-status').textContent='Server OCR is unavailable or could not read this receipt. Try a clearer image or enter it manually.'}}
