function setupAuthExperience(){const panel=$('profile-name')?.closest('.access-panel');if(!panel||$('auth-tabs'))return;const tabs=document.createElement('div');tabs.id='auth-tabs';tabs.className='auth-tabs';tabs.innerHTML='<button type="button" class="auth-tab active" data-auth-mode="login">Log in</button><button type="button" class="auth-tab" data-auth-mode="register">Register</button>';const password=$('profile-password'),register=$('profile-register');panel.insertBefore(tabs,panel.querySelector('label[for="profile-name"]'));const confirmLabel=document.createElement('label');confirmLabel.htmlFor='profile-password-confirm';confirmLabel.textContent='Retype password';const confirm=document.createElement('input');confirm.id='profile-password-confirm';confirm.type='password';confirm.minLength=8;confirm.placeholder='Retype your password';confirm.autocomplete='new-password';panel.insertBefore(confirmLabel,$('profile-list'));panel.insertBefore(confirm,$('profile-list'));const search=document.createElement('input');search.id='username-search';search.type='search';search.placeholder='Search registered usernames';search.setAttribute('aria-label','Search registered usernames');panel.insertBefore(search,$('profile-list'));const toggle=mode=>{const registering=mode==='register';tabs.querySelectorAll('.auth-tab').forEach(tab=>tab.classList.toggle('active',tab.dataset.authMode===mode));password.autocomplete=registering?'new-password':'current-password';confirmLabel.classList.toggle('hidden',!registering);confirm.classList.toggle('hidden',!registering);register.classList.toggle('hidden',!registering);$('profile-enter').classList.toggle('hidden',registering);search.classList.toggle('hidden',registering);$('profile-list').classList.toggle('hidden',registering)};tabs.onclick=event=>{const tab=event.target.closest('.auth-tab');if(tab)toggle(tab.dataset.authMode)};search.oninput=()=>renderProfileList();toggle('login');renderProfileList()}
